(async()=>{
 const en=document.documentElement.lang==='en',t=(a,b)=>en?b:a,$=id=>document.getElementById(id);
 const {londonEpoch,departurePlan,due}=await import('./reminder-rules.mjs');
 const section=document.createElement('section');section.id='proactive';section.className='route-card';section.innerHTML=`<h3>${t('主动出发建议与提醒','Proactive departure advice')}</h3><p>${t('仅在页面打开并运行时检查，标签页休眠可能延迟；关闭页面后不发送提醒。交通时长为手动估计，不读取真实班次。','Checks only while this page is open and running; sleeping tabs may delay checks. No alerts after closing the page. Travel duration is a manual estimate, not live timetable data.')}</p><label><input id="reminderEnabled" type="checkbox" style="width:auto"> ${t('启用本次页面的主动提醒','Enable reminders for this page session')}</label><div class="two-col"><label>${t('完整通勤预计分钟（手动）','Total travel minutes (manual)')}<input id="travelEstimate" type="number" min="1" max="240" value="35"></label><label>${t('课前余量分钟','Pre-class buffer minutes')}<input id="arrivalMargin" type="number" min="0" max="60" value="10"></label><label>${t('提醒提前分钟','Reminder lead minutes')}<input id="reminderLead" type="number" min="0" max="30" value="5"></label><label>${t('雨天额外余量分钟','Extra rain buffer minutes')}<input id="rainMargin" type="number" min="0" max="30" value="5"></label></div><label><input id="watchWeather" type="checkbox" style="width:auto"> ${t('启用天气监测：当前起点坐标发送至 Open-Meteo，每10分钟最多查询一次','Enable weather monitoring: send current origin coordinates to Open-Meteo, at most once per 10 minutes')}</label><p>${t('规则：相关通勤时段任一小时降雨概率≥50%时，使用所设雨天余量；这是可调整的设计规则，不是经过验证的耗时预测。','Rule: use the configured rain buffer when any relevant travel hour has ≥50% rain probability. This adjustable design rule is not a validated delay prediction.')}</p><button id="refreshReminder" type="button" class="outline">${t('重新计算','Recalculate')}</button><p id="reminderPlan" role="status"></p><p id="monitorState"></p><div id="reminderAlert" hidden role="status" style="background:#fff2cf;padding:18px;border-radius:8px;color:#173b2d"><strong id="alertTitle"></strong><p id="alertText"></p><button id="reviewJourney" type="button" class="outline">${t('查看行程','Review journey')}</button> <button id="snoozeReminder" type="button" class="outline">${t('稍后5分钟','Snooze 5 min')}</button> <button id="ignoreReminder" type="button" class="outline">${t('本次课程不再提醒','Ignore this class')}</button></div><details><summary>${t('研究演示（不改变真实计划）','Research demo (does not change the real plan)')}</summary><button id="demoDeparture" type="button" class="outline">${t('演示出发提醒','Demo departure alert')}</button><button id="demoRain" type="button" class="outline">${t('演示天气变化','Demo weather change')}</button><p id="demoResult" role="status"></p></details>`;
 $('classes').after(section);
 let course=null,signature='',rain=null,weatherAt=0,weatherError='',pending=false,version=0,ignored=false,snoozeUntil=0,lastAlert='',weatherKey='',eventReason='';
 const fmt=ms=>new Intl.DateTimeFormat(en?'en-GB':'zh-CN',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(ms);
 function settings(){const v=['travelEstimate','arrivalMargin','reminderLead','rainMargin'].map(id=>Number($(id).value));return v.every((n,i)=>$( ['travelEstimate','arrivalMargin','reminderLead','rainMargin'][i]).value!==''&&Number.isFinite(n))&&v[0]>=1&&v[0]<=240&&v[1]>=0&&v[1]<=60&&v[2]>=0&&v[2]<=30&&v[3]>=0&&v[3]<=30?v:null;}
 function hide(){$('reminderAlert').hidden=true;}
 function resetWeather(){version++;rain=null;weatherAt=0;weatherError='';weatherKey='';eventReason='';}
 function alert(reason,text){$('alertTitle').textContent=reason;$('alertText').textContent=text;$('reminderAlert').hidden=false;}
 function check(){const s=settings();if(!course){$('reminderPlan').textContent=t('选择课程后开始计算。','Select a class to calculate.');hide();return;}const start=londonEpoch(course.day,course.time);if(!s||start===null){$('reminderPlan').textContent=t('参数无效或课程时间处于夏令时切换歧义，请调整。','Invalid settings or ambiguous daylight-saving time; adjust the class time.');hide();return;}
 const current=$('building').value===course.building&&$('classStart').value===course.time&&$('commuteDate').value===course.day;if(!current){$('reminderPlan').textContent=t('课程与通勤设置不一致，需重新选择课程。','Class and journey settings differ; select the class again.');hide();return;}
 const locationKey=signature+':'+Number($('originLat').value)+':'+Number($('originLon').value);
 const wet=$('watchWeather').checked&&rain===true&&weatherKey===locationKey&&Date.now()-weatherAt<15*60000,leave=departurePlan(start,s[0],s[1],wet?s[3]:0),now=Date.now();
 $('reminderPlan').textContent=t('建议出发 ','Suggested departure ')+fmt(leave)+' · '+t('手动通勤 ','Manual travel ')+s[0]+t('分钟，课前余量 ',' min; arrival buffer ')+s[1]+t('分钟，雨天余量 ',' min; rain buffer ')+(wet?s[3]:0)+' min · '+(now>=start?t('课程已开始，不触发出发提醒','Class started; departure alerts suppressed'):t('英国时间','UK time'));
 $('monitorState').textContent=weatherError||($('watchWeather').checked?(weatherAt?t('天气预测获取于 ','Forecast fetched at ')+fmt(weatherAt)+t('；过期后不作为雨天依据。','; stale forecasts are not used.'):t('天气尚未获取，当前不包含天气余量。','No forecast yet; no weather buffer included.')):t('天气监测关闭。','Weather monitoring off.'));
 if(!$('reminderEnabled').checked||ignored||now>=start){hide();return;}
 const reason=eventReason||'departure',key=signature+':'+reason+':'+leave;if(now>=snoozeUntil&&(eventReason||due({now,start,leave,lead:s[2],snoozeUntil,ignored}))&&key!==lastAlert){lastAlert=key;eventReason='';alert(reason==='departure'?t('即将到建议出发时间','Suggested departure approaching'):t('天气条件变化，计划已更新','Weather conditions changed; plan updated'),course.title+' · '+t('建议 ','Suggested ')+fmt(leave)+t(' 出发。依据为手动通勤估计和所设余量；实际班次仍需确认。',' departure. Based on manual travel estimates and configured buffers; confirm actual services.'));}}
 async function weather(){if(!$('reminderEnabled').checked||!$('watchWeather').checked||!course||pending)return;const start=londonEpoch(course.day,course.time),s=settings();if(!start||!s||start<=Date.now()||start-Date.now()>6*86400000)return;const lat=Number($('originLat').value),lon=Number($('originLon').value);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const key=signature+':'+lat+':'+lon;if(weatherKey===key&&Date.now()-weatherAt<600000)return;pending=true;const id=version;try{const u=new URL('https://api.open-meteo.com/v1/forecast');Object.entries({latitude:lat,longitude:lon,hourly:'precipitation_probability',timezone:'Europe/London',timeformat:'unixtime',forecast_days:7}).forEach(([k,v])=>u.searchParams.set(k,v));const r=await fetch(u,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const j=await r.json();if(id!==version)return;const begin=departurePlan(start,s[0],s[1],s[3]);const vals=j.hourly.time.flatMap((x,i)=>x*1000<=start&&x*1000+3600000>begin&&Number.isFinite(j.hourly.precipitation_probability[i])?[j.hourly.precipitation_probability[i]]:[]);if(!vals.length)throw Error();const next=vals.some(v=>v>=50);if(rain!==null&&rain!==next)eventReason='weather';rain=next;weatherAt=Date.now();weatherKey=key;weatherError='';check();}catch{if(id===version){rain=null;weatherAt=Date.now();weatherKey=key;weatherError=t('天气获取失败，不以缺失信息推断晴天；当前仅使用手动估计。','Weather unavailable; missing data does not mean dry conditions. Manual estimates only.');check();}}finally{pending=false;}}
 window.addEventListener('greengo:class-selected',e=>{const c=e.detail;const sig=c.id+':'+c.day+':'+c.time+':'+c.building;if(sig!==signature){signature=sig;ignored=false;snoozeUntil=0;lastAlert='';course=c;resetWeather();hide();}else course=c;check();weather();});
 $('reminderEnabled').onchange=()=>{lastAlert='';check();weather();};$('watchWeather').onchange=()=>{resetWeather();check();weather();};['travelEstimate','arrivalMargin','reminderLead','rainMargin'].forEach(id=>$(id).onchange=()=>{resetWeather();check();weather();});$('refreshReminder').onclick=()=>{check();weather();};
 $('snoozeReminder').onclick=()=>{snoozeUntil=Date.now()+300000;lastAlert='';hide();};$('ignoreReminder').onclick=()=>{ignored=true;hide();};$('reviewJourney').onclick=()=>{$('arrivalFlow').scrollIntoView({behavior:'smooth'});};
 $('demoDeparture').onclick=()=>{$('demoResult').textContent=t('演示：临近建议出发时间，可查看行程、稍后提醒或忽略。未修改真实时钟或提醒状态。','DEMO: departure is approaching. Review, snooze or ignore are available in real alerts. No clock or reminder state changed.');};$('demoRain').onclick=()=>{$('demoResult').textContent=t('演示：降雨概率由低于50%变为≥50%，建议出发时间提前所设雨天余量；真实天气未被修改。','DEMO: rain probability crosses 50%; departure shifts earlier by the configured rain buffer. Actual weather is unchanged.');};
 ['building','classStart','commuteDate','originLat','originLon'].forEach(id=>$(id).addEventListener('change',()=>{resetWeather();hide();check();}));new MutationObserver(()=>{if(!$('classList').querySelector('article')){course=null;signature='';resetWeather();check();}}).observe($('classList'),{childList:true});
 setInterval(()=>{check();weather();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){check();weather();}});check();
})();
